func TestIter(t *testing.T) {
	t.Run("yields sequential attempt numbers with constant duration", func(t *testing.T) {
		var attempts []int64
		var durations []time.Duration
		for attempt, dur := range Iter(Constant(500 * time.Millisecond)) {
			attempts = append(attempts, attempt)
			durations = append(durations, dur)
			if attempt == 4 {
				break
			}
		}
		require.Equal(t, []int64{0, 1, 2, 3, 4}, attempts)
		require.Equal(t, []time.Duration{500 * time.Millisecond, 500 * time.Millisecond, 500 * time.Millisecond, 500 * time.Millisecond, 500 * time.Millisecond}, durations)
	})

	t.Run("yields correct durations for explicit strategy cycling", func(t *testing.T) {
		var attempts []int64
		var durations []time.Duration
		for attempt, dur := range Iter(Explicit(time.Second, 2*time.Second, 3*time.Second)) {
			attempts = append(attempts, attempt)
			durations = append(durations, dur)
			if attempt == 5 {
				break
			}
		}
		require.Equal(t, []int64{0, 1, 2, 3, 4, 5}, attempts)
		require.Equal(t, []time.Duration{time.Second, 2 * time.Second, 3 * time.Second, time.Second, 2 * time.Second, 3 * time.Second}, durations)
	})

	t.Run("yields exponential durations", func(t *testing.T) {
		var attempts []int64
		var durations []time.Duration
		for attempt, dur := range Iter(Exponential(1 * time.Second)) {
			attempts = append(attempts, attempt)
			durations = append(durations, dur)
			if attempt == 3 {
				break
			}
		}
		require.Equal(t, []int64{0, 1, 2, 3}, attempts)
		require.Equal(t, []time.Duration{time.Second, 2 * time.Second, 4 * time.Second, 8 * time.Second}, durations)
	})

	t.Run("stops after first yield when loop breaks immediately", func(t *testing.T) {
		count := 0
		for range Iter(Constant(time.Second)) {
			count++
			break
		}
		require.Equal(t, 1, count)
	})

	t.Run("starts at attempt zero", func(t *testing.T) {
		var firstAttempt int64
		for attempt := range Iter(Constant(time.Second)) {
			firstAttempt = attempt
			break
		}
		require.Equal(t, int64(0), firstAttempt)
	})

	t.Run("yields with multiple option strategy", func(t *testing.T) {
		s := New(Exponential(100*time.Millisecond), Maximum(500*time.Millisecond))
		var durations []time.Duration
		for _, dur := range Iter(s) {
			durations = append(durations, dur)
			if len(durations) == 5 {
				break
			}
		}
		require.Equal(t, []time.Duration{100 * time.Millisecond, 200 * time.Millisecond, 400 * time.Millisecond, 500 * time.Millisecond, 500 * time.Millisecond}, durations)
	})

	t.Run("yields with explicit single delay", func(t *testing.T) {
		var attempts []int64
		var durations []time.Duration
		for attempt, dur := range Iter(Explicit(3 * time.Second)) {
			attempts = append(attempts, attempt)
			durations = append(durations, dur)
			if attempt == 2 {
				break
			}
		}
		require.Equal(t, []int64{0, 1, 2}, attempts)
		require.Equal(t, []time.Duration{3 * time.Second, 3 * time.Second, 3 * time.Second}, durations)
	})
}
